using GseTechPro.Core.Contracts;

namespace GseTechPro.Scope;

/// <summary>
/// Named waveform presets generated by <see cref="SimulatedScopeDevice"/>. Maps 1:1 to the six
/// Phase-6 automotive guided tests plus general-purpose Sine and Square signals.
/// </summary>
public enum SimulatedSignalPreset
{
    /// <summary>General-purpose 1 kHz sine wave (±2.5 V, 5 Vpp).</summary>
    Sine,
    /// <summary>General-purpose 1 kHz square wave (0..5 V, 50% duty).</summary>
    Square,
    /// <summary>Crank sensor (CKP): 60-2 pulse train, ~2.5 Vpp, ~200 Hz on CH1.</summary>
    CrankSensor,
    /// <summary>Injector current: peak-and-hold current pulse, ~1.0 V peak (~10 A @ 10 A/V) on CH2.</summary>
    InjectorCurrent,
    /// <summary>Alternator ripple: small AC ripple, ~0.2 Vpp (DC removed by AC coupling) on CH1.</summary>
    AlternatorRipple,
    /// <summary>Starter current: starter inrush, peak ~3.0 V (~300 A @ 100 A/V), decaying on CH2.</summary>
    StarterCurrent,
    /// <summary>CAN signal quality: CAN frame recessive ~2.5 V / dominant ~0 V on CH1.</summary>
    CanSignalQuality,
    /// <summary>Solenoid current: solenoid current ramp + hold, peak ~1.5 V (~15 A @ 10 A/V) on CH2.</summary>
    SolenoidCurrent,
    /// <summary>CAN frames: simulated J1939 traffic at 250 kbit/s, CAN-H on CH1 and CAN-L on CH2 (ISO 11898-2 nominal
    /// 2.5 V recessive, 3.5 V / 1.5 V dominant), for serial decoding.</summary>
    CanBusFrames,
    /// <summary>Battery / cranking: battery voltage on CH1 and starter-cable current on CH2 (clamp scale from the
    /// channel setup) over a 5 s capture: rest, starter inrush, cranking with compression ripple, engine running.
    /// Demo values for the simulator, not specifications.</summary>
    BatteryCranking,
}

/// <summary>
/// Canonical preset metadata and setup recipes matching the Phase-6 guided-test table.
/// </summary>
public static class SimulatedScopePresets
{
    public static IReadOnlyList<SimulatedSignalPreset> All { get; } =
    [
        SimulatedSignalPreset.Sine,
        SimulatedSignalPreset.Square,
        SimulatedSignalPreset.CrankSensor,
        SimulatedSignalPreset.InjectorCurrent,
        SimulatedSignalPreset.AlternatorRipple,
        SimulatedSignalPreset.StarterCurrent,
        SimulatedSignalPreset.CanSignalQuality,
        SimulatedSignalPreset.SolenoidCurrent,
        SimulatedSignalPreset.CanBusFrames,
        SimulatedSignalPreset.BatteryCranking,
    ];

    /// <summary>Human-readable label for UI preset pickers.</summary>
    public static string GetDisplayName(SimulatedSignalPreset preset) => preset switch
    {
        SimulatedSignalPreset.Sine => "Sine Wave (1 kHz)",
        SimulatedSignalPreset.Square => "Square Wave (1 kHz)",
        SimulatedSignalPreset.CrankSensor => "Crank sensor (CKP)",
        SimulatedSignalPreset.InjectorCurrent => "Injector current",
        SimulatedSignalPreset.AlternatorRipple => "Alternator ripple",
        SimulatedSignalPreset.StarterCurrent => "Starter current",
        SimulatedSignalPreset.CanSignalQuality => "CAN signal quality",
        SimulatedSignalPreset.SolenoidCurrent => "Solenoid current",
        SimulatedSignalPreset.CanBusFrames => "CAN frames (J1939, 250 kbit/s)",
        SimulatedSignalPreset.BatteryCranking => "Battery / cranking",
        _ => preset.ToString(),
    };

    /// <summary>
    /// Returns the canonical <see cref="ScopeCaptureRequest"/> for a given <paramref name="preset"/>.
    /// </summary>
    public static ScopeCaptureRequest GetCanonicalRequest(SimulatedSignalPreset preset) => preset switch
    {
        SimulatedSignalPreset.CrankSensor => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig
                {
                    Channel = 1,
                    Coupling = ScopeCoupling.Dc,
                    ProbeMultiplier = 1.0,
                    CurrentScaleAmpsPerVolt = 0.0,
                    VoltageRangeVolts = 5.0,
                },
            ],
            TimebaseSecondsPerDivision = 0.005, // 5 ms/div
            SampleRateHz = 1_000_000,           // 1 MS/s
            TriggerMode = ScopeTriggerMode.Rising,
            TriggerChannel = 1,
            TriggerLevelVolts = 2.0,
        },

        SimulatedSignalPreset.InjectorCurrent => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig
                {
                    Channel = 2,
                    Coupling = ScopeCoupling.Dc,
                    ProbeMultiplier = 1.0,
                    CurrentScaleAmpsPerVolt = 10.0,
                    VoltageRangeVolts = 1.0,
                },
            ],
            TimebaseSecondsPerDivision = 0.001, // 1 ms/div
            SampleRateHz = 1_000_000,           // 1 MS/s
            TriggerMode = ScopeTriggerMode.Rising,
            TriggerChannel = 2,
            TriggerLevelVolts = 0.5,
        },

        SimulatedSignalPreset.AlternatorRipple => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig
                {
                    Channel = 1,
                    Coupling = ScopeCoupling.Ac,
                    ProbeMultiplier = 1.0,
                    CurrentScaleAmpsPerVolt = 0.0,
                    VoltageRangeVolts = 1.0,
                },
            ],
            TimebaseSecondsPerDivision = 0.010, // 10 ms/div
            SampleRateHz = 100_000,             // 100 kS/s
            TriggerMode = ScopeTriggerMode.Rising,
            TriggerChannel = 1,
            TriggerLevelVolts = 0.05,
        },

        SimulatedSignalPreset.StarterCurrent => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig
                {
                    Channel = 2,
                    Coupling = ScopeCoupling.Dc,
                    ProbeMultiplier = 1.0,
                    CurrentScaleAmpsPerVolt = 100.0,
                    VoltageRangeVolts = 1.0,
                },
            ],
            TimebaseSecondsPerDivision = 0.100, // 100 ms/div
            SampleRateHz = 100_000,             // 100 kS/s
            TriggerMode = ScopeTriggerMode.Rising,
            TriggerChannel = 2,
            TriggerLevelVolts = 0.2,
        },

        SimulatedSignalPreset.CanSignalQuality => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig
                {
                    Channel = 1,
                    Coupling = ScopeCoupling.Dc,
                    ProbeMultiplier = 1.0,
                    CurrentScaleAmpsPerVolt = 0.0,
                    VoltageRangeVolts = 5.0,
                },
            ],
            TimebaseSecondsPerDivision = 0.00005, // 50 µs/div
            SampleRateHz = 20_000_000,            // 20 MS/s
            TriggerMode = ScopeTriggerMode.Rising,
            TriggerChannel = 1,
            TriggerLevelVolts = 2.5,
        },

        SimulatedSignalPreset.CanBusFrames => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig { Channel = 1, Coupling = ScopeCoupling.Dc, ProbeMultiplier = 1.0, VoltageRangeVolts = 5.0 },
                new ScopeChannelConfig { Channel = 2, Coupling = ScopeCoupling.Dc, ProbeMultiplier = 1.0, VoltageRangeVolts = 5.0 },
            ],
            TimebaseSecondsPerDivision = 0.0005, // 500 µs/div: several frames
            SampleRateHz = 5_000_000,            // 5 MS/s = 20 samples per bit at 250 kbit/s
            TriggerMode = ScopeTriggerMode.None,
            TriggerChannel = 1,
            TriggerLevelVolts = 3.0,
        },

        SimulatedSignalPreset.BatteryCranking => new ScopeCaptureRequest
        {
            Channels =
            [
                new ScopeChannelConfig { Channel = 1, Coupling = ScopeCoupling.Dc, ProbeMultiplier = 1.0, VoltageRangeVolts = 20.0 },
                new ScopeChannelConfig
                {
                    Channel = 2,
                    Coupling = ScopeCoupling.Dc,
                    ProbeMultiplier = 1.0,
                    CurrentScaleAmpsPerVolt = 1000.0, // a 1 mV/A high-current clamp
                    VoltageRangeVolts = 1.0,
                },
            ],
            TimebaseSecondsPerDivision = 0.5, // 500 ms/div: 5 s holds rest, crank and start
            SampleRateHz = 10_000,
            TriggerMode = ScopeTriggerMode.None,
            TriggerChannel = 1,
            TriggerLevelVolts = 0.0,
        },

        SimulatedSignalPreset.SolenoidCurrent => new ScopeCaptureRequest
