    /// <summary>
    /// Resolves a guided test name or id (e.g. "Crank sensor (CKP)", "alternator_ripple") to its
    /// matching <see cref="SimulatedSignalPreset"/>.
    /// </summary>
    public static bool TryResolvePreset(string? testNameOrId, out SimulatedSignalPreset preset)
    {
        preset = SimulatedSignalPreset.Sine;
        if (string.IsNullOrWhiteSpace(testNameOrId))
            return false;

        if (Enum.TryParse<SimulatedSignalPreset>(testNameOrId.Trim(), ignoreCase: true, out var parsed))
        {
            preset = parsed;
            return true;
        }

        string normalized = testNameOrId.Trim().ToLowerInvariant();
        if (normalized.Contains("battery") || normalized.Contains("cranking"))
        {
            preset = SimulatedSignalPreset.BatteryCranking;
            return true;
        }
        if (normalized.Contains("crank") || normalized.Contains("ckp"))
        {
            preset = SimulatedSignalPreset.CrankSensor;
            return true;
        }
        if (normalized.Contains("injector"))
        {
            preset = SimulatedSignalPreset.InjectorCurrent;
            return true;
        }
        if (normalized.Contains("alternator") || normalized.Contains("ripple"))
        {
            preset = SimulatedSignalPreset.AlternatorRipple;
            return true;
        }
        if (normalized.Contains("starter") || normalized.Contains("inrush"))
        {
            preset = SimulatedSignalPreset.StarterCurrent;
            return true;
        }
        if (normalized.Contains("can"))
        {
            preset = SimulatedSignalPreset.CanSignalQuality;
            return true;
        }
        if (normalized.Contains("solenoid") || normalized.Contains("valve"))
        {
            preset = SimulatedSignalPreset.SolenoidCurrent;
            return true;
        }
        if (normalized.Contains("square"))
        {
            preset = SimulatedSignalPreset.Square;
            return true;
        }
        if (normalized.Contains("sine"))
        {
            preset = SimulatedSignalPreset.Sine;
            return true;
        }

        return false;
    }

    /// <summary>
    /// Infers the matching canonical preset from a <see cref="ScopeCaptureRequest"/> when no
    /// explicit preset override was configured on the simulator.
    /// </summary>
    public static SimulatedSignalPreset? TryMatchFromCaptureRequest(ScopeCaptureRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);
        if (request.Channels.Count == 0)
            return null;

        var primary = request.Channels[0];

        // One-tap battery / cranking test (500 ms/div at 10 kS/s).
        if (Math.Abs(request.TimebaseSecondsPerDivision - 0.5) < 1e-6 && request.SampleRateHz == 10_000)
            return SimulatedSignalPreset.BatteryCranking;

        // Serial decoding setup (500 µs/div at 5 MS/s): bus traffic rather than one CAN bit pattern.
        if (Math.Abs(request.TimebaseSecondsPerDivision - 0.0005) < 1e-7 && request.SampleRateHz == 5_000_000)
            return SimulatedSignalPreset.CanBusFrames;

        if (request.SampleRateHz >= 10_000_000 || Math.Abs(request.TimebaseSecondsPerDivision - 0.00005) < 1e-7)
            return SimulatedSignalPreset.CanSignalQuality;

        if (primary.Coupling == ScopeCoupling.Ac)
            return SimulatedSignalPreset.AlternatorRipple;

        if (Math.Abs(primary.CurrentScaleAmpsPerVolt - 100.0) < 1e-3)
            return SimulatedSignalPreset.StarterCurrent;

        if (Math.Abs(primary.CurrentScaleAmpsPerVolt - 10.0) < 1e-3)
        {
            return request.TimebaseSecondsPerDivision <= 0.002
                ? SimulatedSignalPreset.InjectorCurrent
                : SimulatedSignalPreset.SolenoidCurrent;
        }

        if (primary.Channel == 1 &&
            Math.Abs(request.TimebaseSecondsPerDivision - 0.005) < 1e-5 &&
            request.SampleRateHz == 1_000_000)
        {
            return SimulatedSignalPreset.CrankSensor;
        }

        return null;
    }
}
